  const w2y = Math.cos(my*0.022-mx*0.015+t*0.35)*8 + Math.sin(mx*0.018+my*0.012+t*0.45)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.9],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.1],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.8],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,1.2],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.7],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,1.0],
    [80+Math.sin(t*0.45+3)*110,120+Math.cos(t*0.65+2)*70,0.11,2.1,0.85],
    [400+Math.cos(t*0.38+1)*95,140+Math.sin(t*0.72+4)*85,0.065,1.8,1.15]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const fo=1.0/(1.0+d*0.003);
    aS+=(Math.sin(d*f-t*sp)+Math.sin(d*f*2.1-t*sp*1.5)*0.3)*w*fo;
    iS+=(Math.sin(d*f*0.7+t*sp*0.6+1.5)+Math.sin(d*f*1.8+t*sp*0.4)*0.25)*w*fo;
    hS+=Math.sin(d*f*0.5-t*sp*0.8+3.0)*w*fo;
  }
  const n=src.length,act=aS/n,inh=iS/n,harm=hS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+sy*0.06-t*1.8)*0.1;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
