  const caust=Math.sin(Math.sin(sx*0.05+t*0.7)*3+Math.cos(sy*0.04-t*0.5)*3+t*1.3)*0.2;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.25;
  const rd2=Math.tanh((act*0.5+harm*0.3-inh*0.4)*1.8);
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+caust+cell)*2.2);
  const blend=reaction*0.6+rd2*0.2+cell*0.1+caust*0.1,v=blend*0.5+0.5;
  const hShift=Math.sin(harm*0.5+t*0.15)*0.12;
  const pal=[[6,12,52],[10,55,95],[18,110,120],[45,165,130],[160,195,80],[210,185,55],[215,135,60],[195,85,65],[160,50,75],[100,28,65],[50,15,55],[6,12,52]];
  const idx=(v+hShift)*(pal.length-1),ci=Math.max(0,Math.min(idx|0,pal.length-2)),f=idx-ci;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2+Math.abs(caust)*0.1;
  const edge=Math.abs(reaction)>0.7?1.2:Math.abs(reaction)>0.4?1.05:1.0;
  const glow=Math.max(0,1.0-dist*0.003)*0.15+Math.max(0,0.5-dist*0.002)*0.1;
  const b=lum*edge+glow;
  return[Math.min(255,(pal[ci][0]+(pal[ci+1][0]-pal[ci][0])*f)*b)|0,Math.min(255,(pal[ci][1]+(pal[ci+1][1]-pal[ci][1])*f)*b)|0,Math.min(255,(pal[ci][2]+(pal[ci+1][2]-pal[ci][2])*f)*b)|0];
}
